ALTER TABLE public.mensagens_marketing ADD COLUMN IF NOT EXISTS organization_id uuid REFERENCES public.organizations(id);
ALTER TABLE public.mensagens_marketing ADD COLUMN IF NOT EXISTS scheduled_for timestamptz;
ALTER TABLE public.mensagens_marketing ADD COLUMN IF NOT EXISTS provider_message_id text;
ALTER TABLE public.mensagens_marketing ADD COLUMN IF NOT EXISTS error_detail text;
ALTER TABLE public.mensagens_marketing ADD COLUMN IF NOT EXISTS campaign_id uuid REFERENCES public.campanhas_marketing(id);
ALTER TABLE public.mensagens_marketing ADD COLUMN IF NOT EXISTS created_by uuid REFERENCES auth.users(id);
ALTER TABLE public.mensagens_marketing DROP CONSTRAINT IF EXISTS mensagens_marketing_status_check;
ALTER TABLE public.mensagens_marketing ADD CONSTRAINT mensagens_marketing_status_check CHECK(status IN ('draft','scheduled','queued','sent','delivered','read','failed','cancelled'));
ALTER TABLE public.mensagens_marketing ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Authenticated full access to mensagens_marketing" ON public.mensagens_marketing;
DROP POLICY IF EXISTS "Allow full access to authenticated users" ON public.mensagens_marketing;
CREATE POLICY marketing_messages_org_access ON public.mensagens_marketing FOR ALL TO authenticated USING (public.is_admin(auth.uid()) OR EXISTS (SELECT 1 FROM public.organization_members m WHERE m.organization_id=mensagens_marketing.organization_id AND m.user_id=auth.uid() AND m.papel::text IN ('admin','manager'))) WITH CHECK (organization_id IS NOT NULL AND (public.is_admin(auth.uid()) OR EXISTS (SELECT 1 FROM public.organization_members m WHERE m.organization_id=mensagens_marketing.organization_id AND m.user_id=auth.uid() AND m.papel::text IN ('admin','manager'))));
CREATE TABLE public.marketing_message_events (id uuid primary key default gen_random_uuid(),message_id uuid not null references public.mensagens_marketing(id) on delete cascade,organization_id uuid not null references public.organizations(id),event_type text not null check(event_type in ('queued','sent','delivered','read','failed','reply')),provider_event_id text,payload jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default now());
ALTER TABLE public.marketing_message_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY marketing_message_events_org_read ON public.marketing_message_events FOR SELECT TO authenticated USING(public.is_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.organization_members m WHERE m.organization_id=marketing_message_events.organization_id AND m.user_id=auth.uid() AND m.papel::text IN ('admin','manager')));
CREATE OR REPLACE FUNCTION public.queue_marketing_message(p_organization_id uuid,p_channel text,p_title text,p_body text,p_recipient_count int,p_scheduled_for timestamptz default null,p_campaign_id uuid default null)
RETURNS public.mensagens_marketing LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v public.mensagens_marketing; BEGIN IF auth.uid() IS NULL OR NOT(public.is_admin(auth.uid()) OR EXISTS(SELECT 1 FROM public.organization_members m WHERE m.organization_id=p_organization_id AND m.user_id=auth.uid() AND m.papel::text IN('admin','manager'))) THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF p_channel NOT IN('email','whatsapp','sms','app') OR length(btrim(coalesce(p_title,'')))<3 OR length(btrim(coalesce(p_body,'')))<3 OR p_recipient_count<1 THEN RAISE EXCEPTION 'Dados de comunicação inválidos'; END IF; INSERT INTO public.mensagens_marketing(organization_id,canal,titulo,corpo,destinatarios,enviadas,status,scheduled_for,campaign_id,created_by) VALUES(p_organization_id,p_channel,p_title,p_body,p_recipient_count,0,CASE WHEN p_scheduled_for IS NULL OR p_scheduled_for<=now() THEN 'queued' ELSE 'scheduled' END,p_scheduled_for,p_campaign_id,auth.uid()) RETURNING * INTO v; INSERT INTO public.marketing_message_events(message_id,organization_id,event_type) VALUES(v.id,p_organization_id,CASE WHEN v.status='queued' THEN 'queued' ELSE 'sent' END); RETURN v; END $$;
REVOKE ALL ON FUNCTION public.queue_marketing_message(uuid,text,text,text,int,timestamptz,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.queue_marketing_message(uuid,text,text,text,int,timestamptz,uuid) TO authenticated;

